// Create Partial Account Name — port of Zap node 316797557
function extractCoreWords(companyName) {
  const stopWords = new Set(['a','an','the','of','and','in','on','at','for','with','co','corp','inc','llc','ltd','company','services']);
  if (!companyName || typeof companyName !== 'string') return { longestWord: null, wordBefore: null, wordAfter: null };
  const words = companyName.trim().split(/\s+/).filter(w => {
    const c = w.toLowerCase().replace(/[^a-z0-9]/gi,'');
    return c && !stopWords.has(c);
  });
  if (!words.length) return { longestWord: null, wordBefore: null, wordAfter: null };
  let idx = 0;
  for (let i = 1; i < words.length; i++) if (words[i].length > words[idx].length) idx = i;
  return {
    longestWord: words[idx],
    wordBefore: idx > 0 ? words[idx-1] : null,
    wordAfter: idx < words.length-1 ? words[idx+1] : null
  };
}
const r = extractCoreWords($json.formattedCompany);
return [{ json: { ...$json, ...r } }];

// Create Queries — port of Zap node 316965886 with SOQL injection escape fix
const { formattedFirst: firstName, formattedLast: lastName, formattedEmail: email, emailDomain, formattedCompany: companyName, longestWord } = $json;
const wordBefore = $json.wordBefore ?? '';
const wordAfter  = $json.wordAfter ?? '';
const esc = (s) => String(s ?? '').replace(/'/g, "\\'");
const publicDomains = new Set(['gmail.com','yahoo.com','hotmail.com','aol.com','outlook.com','icloud.com','msn.com','live.com','protonmail.com','zoho.com','yandex.com','mail.com']);
let contactQuery, leadQuery;
if (publicDomains.has(String(emailDomain).toLowerCase())) {
  contactQuery = `Email = '${esc(email)}' AND (Account.Name = '${esc(companyName)}' OR (Account.Name LIKE '%${esc(wordBefore)}%' AND Account.Name LIKE '%${esc(longestWord)}%' AND Account.Name LIKE '%${esc(wordAfter)}%'))`;
  leadQuery    = `Email = '${esc(email)}' AND (Company = '${esc(companyName)}' OR (Company LIKE '%${esc(wordBefore)}%' AND Company LIKE '%${esc(longestWord)}%' AND Company LIKE '%${esc(wordAfter)}%')) AND IsConverted = False`;
} else {
  contactQuery = `Email_Domain__c = '${esc(emailDomain)}' AND (Email LIKE '%${esc(firstName)}%' OR Email LIKE '%${esc(lastName)}%') AND (Account.Name = '${esc(companyName)}' OR (Account.Name LIKE '%${esc(wordBefore)}%' AND Account.Name LIKE '%${esc(longestWord)}%' AND Account.Name LIKE '%${esc(wordAfter)}%'))`;
  leadQuery    = `Email LIKE '%${esc(emailDomain)}%' AND (Email LIKE '%${esc(firstName)}%' OR Email LIKE '%${esc(lastName)}%') AND (Company = '${esc(companyName)}' OR (Company LIKE '%${esc(wordBefore)}%' AND Company LIKE '%${esc(longestWord)}%' AND Company LIKE '%${esc(wordAfter)}%')) AND IsConverted = False`;
}
return [{ json: { ...$json, contactQuery, leadQuery } }];

